#pragma once

#include <QNetworkAccessManager>
#include <QObject>
#include <QString>
#include <QUrl>

class UpdateChecker : public QObject
{
    Q_OBJECT

public:
    explicit UpdateChecker(const QUrl &url, QObject *parent = nullptr);

    void check();

signals:
    void checked(const QString &version);

private:
    QUrl url_;
    QNetworkAccessManager *manager_;
};

#include "updatechecker.h"

#include <QJsonDocument>
#include <QJsonObject>
#include <QNetworkReply>
#include <QNetworkRequest>

UpdateChecker::UpdateChecker(const QUrl &url, QObject *parent)
    : QObject(parent), url_(url), manager_(new QNetworkAccessManager(this))
{
}

void UpdateChecker::check()
{
    QNetworkReply *reply = manager_->get(QNetworkRequest(url_));
    connect(reply, &QNetworkReply::finished, this, [this, reply] {
        const auto doc = QJsonDocument::fromJson(reply->readAll());
        emit checked(doc.object().value("version").toString());
    });
}

